    validateMemoryInput(key, undefined, undefined, namespace);
    try {
        const result = await getEntry({ key, namespace, dbPath, memoryEntriesOnly: true });
        if (result.success === false || result.error) {
            return {
                key,
                namespace,
                value: null,
                found: false,
                success: false,
                error: typeof result.error === 'string' ? result.error : result.error instanceof Error ? result.error.message : result.error == null ? 'Memory retrieval failed' : JSON.stringify(result.error),
            };
        }
        if (result.found && result.entry) {
            // Try to parse JSON value
            let value = result.entry.content;
            try {
                value = JSON.parse(result.entry.content);
            }
            catch {
                // Keep as string
            }
            return {
                key,
                namespace,
                value,
                tags: result.entry.tags,
                storedAt: result.entry.createdAt,
                updatedAt: result.entry.updatedAt,
                accessCount: result.entry.accessCount,
                hasEmbedding: result.entry.hasEmbedding,
                found: true,
                backend: await describeBackend(),
            };
        }
        return {
            key,
            namespace,
            value: null,
            found: false,
        };
    }
    catch (error) {
        return {
            key,
            namespace,
            value: null,
            found: false,
            success: false,
            error: error instanceof Error ? error.message : 'Unknown error',
        };
    }
},
